1	#!/usr/bin/env node
2	/**
3	 * Port of test7.py: derive two 24-byte PBKDF2 keys from one passphrase and two
4	 * different salts, printing each as lowercase hex.
5	 *
6	 *   key1 = pbkdf2.PBKDF2(a, b).read(24)   -> hex
7	 *   key2 = pbkdf2.PBKDF2(a, c).read(24)   -> hex
8	 *
9	 * Defaults inherited from the Python `pbkdf2` package: HMAC-SHA1 as the PRF and
10	 * 1000 iterations. Both are implemented from scratch under ./lib.
11	 */
12	
13	import { ArgumentParser, ParserExit } from './lib/argparse.mjs';
14	import { PBKDF2 } from './lib/pbkdf2.mjs';
15	import { toHex } from './lib/bytes.mjs';
16	
17	/** Last path component, i.e. argparse's default `prog` (basename of argv[0]). */
18	function basename(path) {
19	  const parts = String(path).split(/[/\\]/);
20	  return parts[parts.length - 1] || String(path);
21	}
22	
23	function buildParser() {
24	  const parser = new ArgumentParser({ prog: basename(process.argv[1] || 'test7.mjs') });
25	  parser.addArgument(['--a'], { required: true }); // passphrase
26	  parser.addArgument(['--b'], { required: true }); // salt1
27	  parser.addArgument(['--c'], { required: true }); // salt2
28	  return parser;
29	}
30	
31	function main() {
32	  const args = buildParser().parseArgs(process.argv.slice(2));
33	
34	  // Each PBKDF2 object is a keystream: read(24) yields T_1 (20 bytes) followed
35	  // by the first 4 bytes of T_2.
36	  const key1 = new PBKDF2(args.a, args.b).read(24);
37	  process.stdout.write(`${toHex(key1)}\n`);
38	
39	  const key2 = new PBKDF2(args.a, args.c).read(24);
40	  process.stdout.write(`${toHex(key2)}\n`);
41	}
42	
43	try {
44	  main();
45	} catch (err) {
46	  if (err instanceof ParserExit) {
47	    // Setting exitCode (rather than calling process.exit) lets the stream
48	    // drain, so piped output is never truncated.
49	    if (err.text) {
50	      if (err.stream === 'stdout') process.stdout.write(err.text);
51	      else process.stderr.write(err.text);
52	    }
53	    process.exitCode = err.code;
54	  } else {
55	    throw err;
56	  }
57	}
58

1	/**
2	 * Byte and encoding primitives.
3	 *
4	 * The internal byte type across every module in this port is `Uint8Array`,
5	 * standing in for Python's immutable `bytes`. Everything here is pure JS: no
6	 * platform hashing, no Buffer, no TextEncoder.
7	 */
8	
9	/** Lookup table for lowercase hex formatting ('00' .. 'ff'). */
10	const HEX_DIGITS = (() => {
11	  const table = new Array(256);
12	  const chars = '0123456789abcdef';
13	  for (let i = 0; i < 256; i += 1) {
14	    table[i] = chars[(i >> 4) & 0xf] + chars[i & 0xf];
15	  }
16	  return table;
17	})();
18	
19	/** True for the byte-ish inputs we accept (Uint8Array and friends). */
20	export function isBytes(value) {
21	  return value instanceof Uint8Array;
22	}
23	
24	/**
25	 * Encode a JS string to UTF-8 bytes, mirroring Python's `str.encode("UTF-8")`.
26	 *
27	 * JS strings are UTF-16 code-unit sequences, so surrogate pairs are combined
28	 * into a single 4-byte sequence. An unpaired surrogate cannot be represented in
29	 * UTF-8; we emit U+FFFD for it (WHATWG behaviour) since such a code unit can
30	 * never reach us from argv anyway -- see the notes in test7.mjs.
31	 */
32	export function utf8Encode(text) {
33	  const str = String(text);
34	  // Worst case is 3 bytes per code unit (4 bytes come from 2 units).
35	  const out = new Uint8Array(str.length * 3);
36	  let n = 0;
37	  for (let i = 0; i < str.length; i += 1) {
38	    let cp = str.charCodeAt(i);
39	    if (cp >= 0xd800 && cp <= 0xdbff) {
40	      // High surrogate: pair it with a following low surrogate if present.
41	      const next = i + 1 < str.length ? str.charCodeAt(i + 1) : 0;
42	      if (next >= 0xdc00 && next <= 0xdfff) {
43	        cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
44	        i += 1;
45	      } else {
46	        cp = 0xfffd; // lone high surrogate
47	      }
48	    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
49	      cp = 0xfffd; // lone low surrogate
50	    }
51	
52	    if (cp < 0x80) {
53	      out[n++] = cp;
54	    } else if (cp < 0x800) {
55	      out[n++] = 0xc0 | (cp >> 6);
56	      out[n++] = 0x80 | (cp & 0x3f);
57	    } else if (cp < 0x10000) {
58	      out[n++] = 0xe0 | (cp >> 12);
59	      out[n++] = 0x80 | ((cp >> 6) & 0x3f);
60	      out[n++] = 0x80 | (cp & 0x3f);
61	    } else {
62	      out[n++] = 0xf0 | (cp >> 18);
63	      out[n++] = 0x80 | ((cp >> 12) & 0x3f);
64	      out[n++] = 0x80 | ((cp >> 6) & 0x3f);
65	      out[n++] = 0x80 | (cp & 0x3f);
66	    }
67	  }
68	  return out.subarray(0, n);
69	}
70	
71	/**
72	 * Coerce str-or-bytes to bytes, the way the Python pbkdf2 package coerces its
73	 * passphrase/salt arguments (`if not isinstance(x, bytes): x = x.encode("UTF-8")`).
74	 */
75	export function asBytes(value) {
76	  if (isBytes(value)) return value;
77	  if (typeof value === 'string') return utf8Encode(value);
78	  if (Array.isArray(value)) return new Uint8Array(value);
79	  throw new TypeError('expected a string or Uint8Array');
80	}
81	
82	/** Lowercase hex with no separators, i.e. Python's `bytes.hex()`. */
83	export function toHex(bytes) {
84	  const b = asBytes(bytes);
85	  let out = '';
86	  for (let i = 0; i < b.length; i += 1) out += HEX_DIGITS[b[i]];
87	  return out;
88	}
89	
90	/** Concatenate any number of byte arrays into one fresh array. */
91	export function concat(...parts) {
92	  let total = 0;
93	  for (const part of parts) total += part.length;
94	  const out = new Uint8Array(total);
95	  let offset = 0;
96	  for (const part of parts) {
97	    out.set(part, offset);
98	    offset += part.length;
99	  }
100	  return out;
101	}
102	
103	/** Copying slice (never a view), so callers can't alias internal buffers. */
104	export function slice(bytes, start, end) {
105	  return bytes.slice(start, end);
106	}
107	
108	/**
109	 * Store an unsigned big-endian integer of `width` bytes at `offset`.
110	 * Used for PBKDF2's block counter and SHA-1's length field.
111	 */
112	export function writeUintBE(target, offset, value, width) {
113	  let v = value;
114	  for (let i = width - 1; i >= 0; i -= 1) {
115	    target[offset + i] = v & 0xff;
116	    v = Math.floor(v / 256);
117	  }
118	  return target;
119	}
120	
121	/** Python `struct.pack("!L", value)`: 4-byte big-endian unsigned. */
122	export function packUint32BE(value) {
123	  if (!Number.isInteger(value) || value < 0 || value > 0xffffffff) {
124	    throw new RangeError('value out of range for 32-bit big-endian packing');
125	  }
126	  return writeUintBE(new Uint8Array(4), 0, value, 4);
127	}
128	
129	/** Python `struct.pack("!Q", value)`: 8-byte big-endian unsigned. */
130	export function packUint64BE(value) {
131	  return writeUintBE(new Uint8Array(8), 0, value, 8);
132	}
133	
134	/** Elementwise XOR of two equal-length arrays (Python pbkdf2's `strxor`). */
135	export function xor(a, b) {
136	  if (a.length !== b.length) {
137	    throw new RangeError('xor operands must be the same length');
138	  }
139	  const out = new Uint8Array(a.length);
140	  for (let i = 0; i < a.length; i += 1) out[i] = a[i] ^ b[i];
141	  return out;
142	}
143	
144	/** In-place XOR of `target` with `source` (same length). Returns `target`. */
145	export function xorInto(target, source) {
146	  if (target.length !== source.length) {
147	    throw new RangeError('xor operands must be the same length');
148	  }
149	  for (let i = 0; i < target.length; i += 1) target[i] ^= source[i];
150	  return target;
151	}
152	
153	/** XOR every byte with one constant -- HMAC's ipad/opad construction. */
154	export function xorWithByte(bytes, constant) {
155	  const out = new Uint8Array(bytes.length);
156	  for (let i = 0; i < bytes.length; i += 1) out[i] = bytes[i] ^ constant;
157	  return out;
158	}
159	
160	/** Zero-extend (or truncate) to exactly `length` bytes. */
161	export function zeroPad(bytes, length) {
162	  const out = new Uint8Array(length);
163	  out.set(bytes.subarray(0, length));
164	  return out;
165	}
166

1	/**
2	 * PBKDF2 (RFC 2898 / PKCS#5 v2.0) as a readable keystream, mirroring the API
3	 * surface of Dwayne Litzenberger's `pbkdf2` PyPI package.
4	 *
5	 * The distinguishing feature of that package (versus hashlib.pbkdf2_hmac) is
6	 * that `read(n)` is a *stream*: derived blocks T_1, T_2, ... are produced on
7	 * demand, n bytes are handed back, and any surplus stays buffered for the next
8	 * read. With SHA-1 (20-byte blocks) a `read(24)` therefore consumes T_1 in full
9	 * plus the first 4 bytes of T_2, leaving 16 bytes buffered.
10	 */
11	
12	import { asBytes, concat, packUint32BE, toHex, xorInto } from './bytes.mjs';
13	import { SHA1 } from './sha1.mjs';
14	import { HMACModule } from './hmac.mjs';
15	
16	/** Largest block index representable in the 4-byte INT32_BE counter. */
17	const MAX_BLOCKS = 0xffffffff;
18	
19	export class PBKDF2 {
20	  /**
21	   * @param {Uint8Array|string} passphrase  UTF-8 encoded if a string.
22	   * @param {Uint8Array|string} salt        UTF-8 encoded if a string.
23	   * @param {number} [iterations=1000]      Iteration count c.
24	   * @param {object} [digestmodule=SHA1]    Digest module for the PRF.
25	   * @param {object} [macmodule=HMACModule] MAC module wrapping the digest.
26	   */
27	  constructor(passphrase, salt, iterations = 1000, digestmodule = SHA1, macmodule = HMACModule) {
28	    if (!Number.isInteger(iterations) || iterations < 1) {
29	      throw new RangeError('iterations must be an integer >= 1');
30	    }
31	
32	    this.passphrase = asBytes(passphrase);
33	    this.salt = asBytes(salt);
34	    this.iterations = iterations;
35	    this.digestmodule = digestmodule;
36	    this.macmodule = macmodule;
37	
38	    /** Size of one derived block, hLen in RFC 2898 (20 for SHA-1). */
39	    this.blockLength = digestmodule.digestSize;
40	
41	    /** Leftover keystream bytes from the previous read(). */
42	    this.buffer = new Uint8Array(0);
43	    /** Index of the highest block already generated; blocks are 1-based. */
44	    this.blockNum = 0;
45	    this.closed = false;
46	
47	    // The PRF key (the passphrase) never changes, so precompute the HMAC key
48	    // schedule once and clone it per call instead of re-padding every time.
49	    this.prfTemplate = macmodule.new(this.passphrase, undefined, digestmodule);
50	  }
51	
52	  /** PRF(passphrase, msg) -- HMAC-SHA1 by default. */
53	  pseudorandom(msg) {
54	    return this.prfTemplate.copy().update(msg).digest();
55	  }
56	
57	  /**
58	   * Read `count` bytes of keystream, generating whole blocks as needed and
59	   * buffering the remainder. Equivalent to the Python package's `read()`.
60	   */
61	  read(count) {
62	    if (this.closed) throw new Error('file-like object is closed');
63	    if (!Number.isInteger(count) || count < 0) {
64	      throw new RangeError('count must be a non-negative integer');
65	    }
66	
67	    const parts = [this.buffer];
68	    let size = this.buffer.length;
69	    let i = this.blockNum;
70	    while (size < count) {
71	      i += 1;
72	      const block = this._deriveBlock(i);
73	      parts.push(block);
74	      size += block.length;
75	    }
76	
77	    const buf = concat(...parts);
78	    this.blockNum = i;
79	    this.buffer = buf.slice(count);
80	    return buf.slice(0, count);
81	  }
82	
83	  /** Read `count` bytes and return them as a lowercase hex string. */
84	  hexread(count) {
85	    return toHex(this.read(count));
86	  }
87	
88	  /** Release the derived state; further reads raise, like the Python class. */
89	  close() {
90	    if (!this.closed) {
91	      this.passphrase = new Uint8Array(0);
92	      this.salt = new Uint8Array(0);
93	      this.buffer = new Uint8Array(0);
94	      this.prfTemplate = null;
95	      this.closed = true;
96	    }
97	  }
98	
99	  /**
100	   * T_i = U_1 ^ U_2 ^ ... ^ U_c, where
101	   *   U_1 = PRF(P, S || INT32_BE(i)) and U_j = PRF(P, U_{j-1}).
102	   */
103	  _deriveBlock(i) {
104	    if (i < 1 || i > MAX_BLOCKS) {
105	      throw new RangeError('PBKDF2 block index out of range');
106	    }
107	    let u = this.pseudorandom(concat(this.salt, packUint32BE(i)));
108	    const result = u.slice(); // accumulator, XOR-folded in place
109	    for (let j = 2; j <= this.iterations; j += 1) {
110	      u = this.pseudorandom(u);
111	      xorInto(result, u);
112	    }
113	    return result;
114	  }
115	}
116	
117	/**
118	 * Module-level convenience mirroring `pbkdf2.crypt`-style one-shot use: derive
119	 * exactly `dkLen` bytes and discard the stream.
120	 */
121	export function pbkdf2(passphrase, salt, dkLen, iterations = 1000, digestmodule = SHA1) {
122	  const stream = new PBKDF2(passphrase, salt, iterations, digestmodule);
123	  const out = stream.read(dkLen);
124	  stream.close();
125	  return out;
126	}
127	
128	export default PBKDF2;
