// Unicode input-class cases for test7 differential testing.
// Each case: { id, label, argv: [ '--a', A, '--b', B, '--c', C ] }
// Invisible / ambiguous characters are written as \u / \u{} escapes on purpose.

const K = (a, b, c) => ['--a', a, '--b', b, '--c', c];

export const cases = [];
let n = 0;
function add(label, argv) {
  n += 1;
  cases.push({ id: n, label, argv });
}
function T(label, a, b, c) { add(label, K(a, b, c)); }

/* ---------- CJK ---------- */
T('cjk: simplified chinese', '中文密码', '盐一', '盐二');
T('cjk: japanese kana+kanji', '日本語パスワード', 'ソルト1', 'ソルト2');
