T('cjk: mixed ascii + hanzi salts', '你好世界', 'salt_中文', 'salt_日本');
T('cjk: ext-B astral vs ext-A bmp', '漢字仮名交じり文', '\u{20000}\u{20001}', '㐀㐁');
