T('marks: thai with tone marks', 'สวัสดี', 'ก่', 'ก้');
T('marks: devanagari conjuncts', 'नमस्ते', 'नमक', 'लवण');
T('marks: arabic with/without harakat', 'كلمة المرور', 'ملح', 'مِلْح');
T('marks: hebrew with niqqud', 'סיסמה', 'מֶלַח', 'מלח');

/* ---------- invisible / format characters ---------- */
T('invisible: BOM U+FEFF leading', '﻿pass', '﻿salt', 'salt');
T('invisible: ZWSP / ZWNJ / ZWJ alone', '​', '‌', '‍');
T('invisible: bidi marks and override', 'a‎b', 'a‏b', 'a‮b‬');
T('invisible: soft hyphen and NBSP', 'so­ft', 'a b', 'a b');
T('invisible: word joiner / narrow nbsp', 'a⁠b', 'a b', 'a b');

/* ---------- astral non-emoji ---------- */
T('astral: deseret / gothic / old italic', '\u{10400}\u{10401}', '\u{10330}\u{10331}', '\u{10300}');
T('astral: musical + math alphanumerics', '\u{1d11e}\u{1d122}', '\u{1d400}\u{1d401}', '\u{1d49c}');
T('astral: plane-16 max codepoints', '\u{10ffff}', '\u{10fffe}', '\u{100000}');
T('astral: linear b / cuneiform / hieroglyph', '\u{10000}\u{10001}', '\u{12000}\u{12001}', '\u{13000}');

/* ---------- UTF-8 length boundaries ---------- */
T('boundary: 1/2-byte edge U+007F/U+0080', '', '', 'ÿ');
T('boundary: 2/3-byte edge U+07FF/U+0800', '߿', 'ࠀ', '࿿');
T('boundary: 3/4-byte edge U+FFFF/U+10000', '￿', '\u{10000}', '�');
T('boundary: one of each width', 'ab߿cࠀd\u{10000}e', '߿ࠀ\u{10000}', 'abcd');
T('boundary: noncharacters U+FDD0..U+FFFE', '﷐﷯', '￾', '￿');

/* ---------- HMAC key-length boundaries in UTF-8 bytes ---------- */
T('len: passphrase 63 bytes (21 x 3B CJK)', '中'.repeat(21), 's1', 's2');
T('len: passphrase 64 bytes (16 x 4B emoji)', '\u{1f600}'.repeat(16), 's1', 's2');
T('len: passphrase 65 bytes (64B emoji + a)', '\u{1f600}'.repeat(16) + 'a', 's1', 's2');
T('len: passphrase 66 bytes (22 x 3B CJK)', '中'.repeat(22), 's1', 's2');
T('len: passphrase 67/68 byte odd split', '中'.repeat(21) + 'éé', '中'.repeat(22), '中'.repeat(21));
T('len: long multibyte salts (>64B)', '\u{1f9c2}', 'ソ'.repeat(40), 'с'.repeat(60));
