#!/usr/bin/env node
// Differential harness: reference (Python-built binary) vs Node port.
// Passes an argv ARRAY (no shell) so both children receive byte-identical argv.

import { spawnSync } from 'node:child_process';
import { cases } from './cases.mjs';

const REF = '/workspace/dataset/test7_executable';
const PORT_ARGS = ['/output/test7.mjs'];
const NODE = process.execPath;

function run(cmd, args, argv) {
  return spawnSync(cmd, [...args, ...argv], {
    encoding: 'buffer',
    maxBuffer: 64 * 1024 * 1024,
    env: { ...process.env, PYTHONIOENCODING: undefined },
  });
}

function hexdump(buf) {
  return Buffer.from(buf || []).toString('hex');
}
function show(buf) {
  const b = Buffer.from(buf || []);
  return JSON.stringify(b.toString('utf8'));
}
// Unambiguous rendering of an argv element: escapes every non-printable-ASCII cp.
function esc(s) {
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp >= 0x20 && cp < 0x7f) out += ch;
    else out += '\\u{' + cp.toString(16) + '}';
  }
  return out;
}
function argvRepr(argv) {
  return '[' + argv.map((a) => `'${esc(a)}'`).join(', ') + ']';
}
function utf8bytes(argv) {
  return argv.map((a) => Buffer.from(a, 'utf8').toString('hex')).join(' | ');
}

const only = process.argv[2] ? new Set(process.argv[2].split(',').map(Number)) : null;

let total = 0;
let match = 0;
const mismatches = [];

for (const tc of cases) {
  if (only && !only.has(tc.id)) continue;
  total += 1;
  const r = run(REF, [], tc.argv);
  const p = run(NODE, PORT_ARGS, tc.argv);

  if (r.error) throw new Error(`ref spawn error case ${tc.id}: ${r.error}`);
  if (p.error) throw new Error(`port spawn error case ${tc.id}: ${p.error}`);

  const outEq = Buffer.compare(Buffer.from(r.stdout), Buffer.from(p.stdout)) === 0;
  const errEq = Buffer.compare(Buffer.from(r.stderr), Buffer.from(p.stderr)) === 0;
  const codeEq = r.status === p.status && r.signal === p.signal;

  if (outEq && errEq && codeEq) {
    match += 1;
  } else {
    mismatches.push({ tc, r, p, outEq, errEq, codeEq });
    console.log('='.repeat(78));
    console.log(`MISMATCH case #${tc.id}  (${tc.label})`);
    console.log(`  argv        : ${argvRepr(tc.argv)}`);
    console.log(`  argv utf8   : ${utf8bytes(tc.argv)}`);
    console.log(`  diff in     : ${[!outEq && 'stdout', !errEq && 'stderr', !codeEq && 'exitcode'].filter(Boolean).join(', ')}`);
    console.log(`  ref  exit   : ${r.status}  signal=${r.signal}`);
    console.log(`  port exit   : ${p.status}  signal=${p.signal}`);
    console.log(`  ref  stdout : ${show(r.stdout)}`);
    console.log(`  port stdout : ${show(p.stdout)}`);
    console.log(`  ref  stdout hex : ${hexdump(r.stdout)}`);
    console.log(`  port stdout hex : ${hexdump(p.stdout)}`);
    console.log(`  ref  stderr : ${show(r.stderr)}`);
    console.log(`  port stderr : ${show(p.stderr)}`);
    console.log(`  ref  stderr hex : ${hexdump(r.stderr)}`);
    console.log(`  port stderr hex : ${hexdump(p.stderr)}`);
  }
}

console.log('='.repeat(78));
console.log(`TOTAL=${total} MATCH=${match} MISMATCH=${total - match}`);

#!/usr/bin/env node
// Sanity-inspect the case table: print codepoints + UTF-8 byte length per arg,
// so "looks identical" cases (NFC/NFD, VS16, homoglyphs) can be verified real.
import { cases } from './cases.mjs';

function cps(s) {
  return [...s].map((ch) => 'U+' + ch.codePointAt(0).toString(16).toUpperCase().padStart(4, '0')).join(' ');
}
for (const tc of cases) {
  console.log(`#${tc.id} ${tc.label}`);
  for (let i = 0; i < tc.argv.length; i += 2) {
    const flag = tc.argv[i];
    const val = tc.argv[i + 1];
    if (val === undefined) {
      console.log(`    ${flag}  (inline)  bytes=${Buffer.byteLength(flag, 'utf8')}  ${cps(flag)}`);
    } else {
      console.log(`    ${flag} bytes=${Buffer.byteLength(val, 'utf8')}  ${cps(val)}`);
    }
  }
}
console.log(`CASES=${cases.length}`);

